def _get_wallet_or_404(self, wallet_id: str) -> dict:
    try:
        wallet = self._store.get_wallet(wallet_id)
    except CorruptDataError:
        # 钱包元数据损坏：fail-closed（由 HTTP 边界转 503），绝不
        # 当成普通 400 或返回半完成公钥
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")
    if wallet is None:
        raise ServiceError(404, f"wallet {wallet_id!r} not found")
    return wallet

# ---- 钱包应急冻结/解冻 ----------------------------------------------

@staticmethod
def _validate_freeze_reason(reason: object) -> str:
    """freeze/unfreeze 请求体 reason：必须是 1..1024 字符的非空白
    字符串（bool 拒绝；仅空白拒绝）。非法抛 ServiceError(400)。"""
    if not isinstance(reason, str) or isinstance(reason, bool):
        raise ServiceError(400, "reason must be a string")
    if len(reason) < 1 or len(reason) > MAX_REASON_LENGTH:
        raise ServiceError(
            400,
            f"reason must be 1 to {MAX_REASON_LENGTH} characters long",
        )
    if not reason.strip():
        raise ServiceError(400, "reason must be non-blank")
    return reason

@staticmethod
def _security_state_view(
    wallet_id: str, state: str, reason: object
) -> dict:
    """安全状态对外视图，固定键序 wallet_id,state,reason；
    active 时 reason 恒为 null。"""
    return {
        "wallet_id": wallet_id,
        "state": state,
        "reason": reason,
    }

def _freeze_events_strict(self, wallet_id: str) -> list[dict]:
    """按 seq 升序返回该钱包全部 wallet_frozen/wallet_unfrozen 事件，
    逐条严格校验并核对交替状态机（调用方须持钱包事务锁）。

    每条事件的 request_id/actor_id/reason 必须为 null，details 恰为
    ``{"reason": <1..1024 字符非空白字符串>}``；事件必须严格交替：
    首条必为 wallet_frozen（active -> frozen），其后 frozen/unfrozen
    轮流出现（frozen -> active -> frozen ...）。任何畸形或同态连续
    （重复 freeze / 重复 unfreeze）都是不可对账现场（RecoveryError，
    fail-closed），绝不静默取最后一条。审计 JSON 损坏由下层抛
    CorruptDataError，文件 I/O 失败抛 OSError。纯只读，不记事件、
    不改 seq。"""
    events = [
        event
        for event in self._audit.all_events(wallet_id)
        if event.get("type")
        in (audit.TYPE_WALLET_FROZEN, audit.TYPE_WALLET_UNFROZEN)
    ]
    expected = audit.TYPE_WALLET_FROZEN
    for event in events:
        if (
            event.get("request_id") is not None
            or event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a freeze event with "
                "request_id/actor_id/reason set"
            )
        details = event.get("details")
        reason = (
            details.get("reason")
            if isinstance(details, dict)
            else None
        )
        if (
            not isinstance(details, dict)
            or set(details) != {"reason"}
            or not isinstance(reason, str)
            or isinstance(reason, bool)
            or len(reason) < 1
            or len(reason) > MAX_REASON_LENGTH
            or not reason.strip()
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a malformed freeze event"
            )
        if event.get("type") != expected:
            raise RecoveryError(
                f"wallet {wallet_id!r} has non-alternating freeze events"
            )
        expected = (
            audit.TYPE_WALLET_UNFROZEN
            if expected == audit.TYPE_WALLET_FROZEN
            else audit.TYPE_WALLET_FROZEN
        )
    return events

def _security_state_locked(self, wallet_id: str) -> dict:
    """按审计事件折叠当前安全状态（调用方须持钱包事务锁）。

    状态只由 wallet_frozen/wallet_unfrozen 事件承载：无事件为
    active（reason=null）；有事件时末条为 frozen 即 frozen，reason
    取**最近一次 freeze** 的 reason；末条为 unfrozen 即 active。
    矛盾/损坏现场 fail-closed。纯只读，不新增事件、不改 seq。"""
    events = self._freeze_events_strict(wallet_id)
    if not events or events[-1]["type"] == audit.TYPE_WALLET_UNFROZEN:
        return self._security_state_view(
            wallet_id, WALLET_STATE_ACTIVE, None
        )
    reason = events[-1]["details"]["reason"]
    return self._security_state_view(
        wallet_id, WALLET_STATE_FROZEN, reason
    )

def _assert_wallet_active_locked(self, wallet_id: str) -> None:
    """frozen 钱包的既有写接口统一 409（调用方须持钱包事务锁）。

    在钱包存在性判定之后、任何参数/幂等/业务判定之前调用：冻结是
    应急闸门，frozen 期间只有查询、审计读取、security-state、
    freeze 与 unfreeze 可用，故即便请求本来会命中幂等 200 重放也一律
    409 且零副作用（不触发懒过期、不追加事件、不改现场）。"""
    if (
        self._security_state_locked(wallet_id)["state"]
        == WALLET_STATE_FROZEN
    ):
        raise ServiceError(
            409, f"wallet {wallet_id!r} is frozen"
        )

def freeze_wallet(
    self, wallet_id: str, reason: object
) -> tuple[int, dict]:
    """POST /v1/wallets/<id>/freeze。返回 (201|200, 安全状态视图)。

    active -> frozen 首次转换 201，在每钱包跨进程事务锁内原子判定并
    追加唯一 wallet_frozen 事件（details 恰为 {"reason": ...}）；
    frozen 期间同 reason 重放 200（不复查、不记事件），异 reason
    409。并发同一操作只有一个 201，其余同参得到 200，审计 seq 连续
    不重号。reason 非字符串/空白/超长 400；钱包不存在 404。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性在锁内、heal 之后先判定
            self._get_wallet_or_404(wallet_id)
            self._validate_freeze_reason(reason)
            state = self._security_state_locked(wallet_id)
            if state["state"] == WALLET_STATE_FROZEN:
                # 已冻结：仅允许与最近一次 freeze 同 reason 的重放
                if state["reason"] != reason:
                    raise ServiceError(
                        409,
                        f"wallet {wallet_id!r} is frozen with a "
                        "different reason",
                    )
                return 200, state
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_WALLET_FROZEN,
                    details={"reason": reason},
                ),
            )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._security_state_view(
        wallet_id, WALLET_STATE_FROZEN, reason
    )

def unfreeze_wallet(
    self, wallet_id: str, reason: object
) -> tuple[int, dict]:
    """POST /v1/wallets/<id>/unfreeze。返回 (201|200, 安全状态视图)。

    frozen -> active 首次转换 201，在每钱包跨进程事务锁内原子判定并
    追加唯一 wallet_unfrozen 事件（details 恰为 {"reason": ...}）；
    active 期间仅当存在同类转换记录（最近一次 unfreeze）且 reason
    相同才重放 200，无 unfreeze 记录或异 reason 一律 409。reason
    非字符串/空白/超长 400；钱包不存在 404。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性在锁内、heal 之后先判定
            self._get_wallet_or_404(wallet_id)
            self._validate_freeze_reason(reason)
            events = self._freeze_events_strict(wallet_id)
            if (
                events
                and events[-1]["type"] == audit.TYPE_WALLET_FROZEN
            ):
                # 当前 frozen（末条为 freeze）：首提解冻。
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_WALLET_UNFROZEN,
                        details={"reason": reason},
                    ),
                )
                return 201, self._security_state_view(
                    wallet_id, WALLET_STATE_ACTIVE, None
                )
            # 当前 active（含从未冻结过的天然 active）：必须存在最近
            # 一次 unfreeze 记录且 reason 相同才允许幂等重放；无
            # unfreeze 记录或异 reason 一律 409。
            last_unfrozen = next(
                (
                    event
                    for event in reversed(events)
                    if event["type"] == audit.TYPE_WALLET_UNFROZEN
                ),
                None,
            )
            if (
                last_unfrozen is not None
                and last_unfrozen["details"]["reason"] == reason
            ):
                return 200, self._security_state_view(
                    wallet_id, WALLET_STATE_ACTIVE, None
                )
            raise ServiceError(
                409, f"wallet {wallet_id!r} is not frozen"
            )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def get_security_state(self, wallet_id: str) -> dict:
    """GET /v1/wallets/<id>/security-state：始终 200 返回
    ``{wallet_id,state,reason}``，active 时 reason 为 null。

    纯只读（不触发懒过期、不记事件）；冻结事件损坏/矛盾 fail-closed
    （由 HTTP 边界转 503）。钱包不存在 404。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先：锁内先判定钱包存在，再折叠冻结事件
            self._get_wallet_or_404(wallet_id)
            return self._security_state_locked(wallet_id)
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")

def put_policy(
    self,
    wallet_id: str,
    required_approvals: object,
    timeout_seconds: object,
) -> dict:
    # 读取（钱包存在性、旧策略）、校验、持久化与事件追加全部在同一把
    # 每钱包事务锁内完成：多个 serve 进程并发更新同一钱包策略时，
    # operation(created|updated) 严格依据锁内旧值，policy_updated 的
    # seq 顺序即策略线性化顺序，绝不基于锁外陈旧快照判定。

#: 在归一化前就须按 README 既定键序严格核对 details 的事件类型集合。
#: 这些事件的 details 落盘保序、读取时由 _order_event_details 就地重排；
#: 若先归一再校验，外部对键序的篡改会被静默抹平，故必须在归一化之前核对
#: **落盘原序**——错序即不可对账现场（RecoveryError），绝不归一。坏 JSON
#: 在更上层的 json 解析处即为 CorruptDataError。
#: dkg_failover 手工/旧事件恰为 id,round,action,node,replacement,key,state
#: 七键序，自动替补事件为既有七键加末键 mode（mode="auto"），两种既定键序
#: 之外的重排同样错序即 RecoveryError。
_STRICT_DETAILS_ORDER_TYPES = frozenset(
    (
        TYPE_NODE_REJOINED,
        TYPE_SHARE_PARTICIPANT_REINSTATED,
        TYPE_DKG_FAILOVER,
        TYPE_CHAIN_DISPATCH_REQUESTED,
        TYPE_CHAIN_DISPATCH_AUTO_REQUESTED,
        TYPE_CHAIN_DISPATCH_RESULT,
        TYPE_CHAIN_DISPATCH_CONFIRMATION,
        TYPE_CHAIN_DISPATCH_SETTLED,
        TYPE_CHAIN_DISPATCH_REORGED,
        TYPE_CHAIN_DISPATCH_TAKEN_OVER,
        TYPE_CHAIN_DISPATCH_ISOLATED,
        TYPE_POLICY_CHANGE_APPLIED,
    )
)


#: 审计事件落盘的外层七字段规范键序（写盘按 sort_keys，见
#: _canonical_event）。正常现场恒为此序，任何重排都是外部篡改。
_OUTER_KEY_ORDER = (
    "actor_id",
    "at",
    "details",
    "reason",
    "request_id",
    "seq",
    "type",
)

#: 在归一化前就须按落盘规范序严格核对**外层七字段**键序的事件类型集合。
#: 读取不重排外层键序，故落盘原序在加载时即可核对：错序即不可对账现场
#: （RecoveryError），且 _read_strict 是追加写盘前的唯一加载路径，错序
#: 现场绝不写盘。
_STRICT_OUTER_ORDER_TYPES = frozenset(
    (
        TYPE_DKG_FAILOVER,
    )
)


def _stored_details_has_canonical_order(event: dict) -> bool:
    """判定一条落盘事件的 details 是否恰为 README 既定键序（归一化之前）。

    仅用于 :data:`_STRICT_DETAILS_ORDER_TYPES` 中的类型。对带多种精确
    键集的类型，details 键集须恰等于其中某一种既定键序；否则即视为错序。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return True
    if order and isinstance(order[0], tuple):
        return any(
            list(details) == list(candidate)
            for candidate in order
            if set(details) == set(candidate)
        )
    return list(details) == list(order)


def _order_event_details(event: dict) -> None:
    """把既定事件类型的 details 就地重排为 README 既定键序。

    仅当 details 键集与既定键序恰好一致时重排；键集不符的现场留给各
    语义对账路径 fail-closed，绝不在这里猜写。chain_vote 事件按精确
    键集在策略序 {sources,quorum} 与票序 {source,report,state} 间选择
    （两种语义共用同一事件类型）。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return
    if order and isinstance(order[0], tuple):
        matched = next(
            (candidate for candidate in order if set(details) == set(candidate)),
            None,
        )
        if matched is None:
            return
        event["details"] = {key: details[key] for key in matched}
        return
    if set(details) != set(order):
        return
    event["details"] = {key: details[key] for key in order}


def _canonicalize_sorted(value: object) -> object:
    """递归重排为 sort_keys 规范序（与 WalletStore._atomic_write 同字节）。"""
    if isinstance(value, dict):
        return {k: _canonicalize_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_canonicalize_sorted(item) for item in value]
    return value


#: 重组补偿提交事件 asset_operation_committed 的 details（即 committed 视图
#: R）固定键序：operation_id,asset_id,delta,state,balance,version。仅适用
#: 于紧邻 chain_dispatch_reorged 之后、同 request_id 的那一条提交事件（重组
#: 三事件批的收尾事件）；普通提交/链上确认/仲裁/结算的提交事件维持既有
#: sort_keys 落盘序，行为不变。
_ASSET_OPERATION_R_KEY_ORDER = (
    "operation_id",
    "asset_id",
    "delta",
    "state",
    "balance",
    "version",
)


def _reorg_compensation_commit(events: list, index: int) -> bool:
    """判定物理序列 index 处的 asset_operation_committed 事件是否为重组补偿
    三事件批（chain_dispatch_confirmation(state=reorged) +
    chain_dispatch_reorged + asset_operation_committed）的收尾提交事件：按
    seq 其紧邻前一条必须是同 request_id 的 chain_dispatch_reorged。"""
    event = events[index]
    if not isinstance(event, dict):
        return False
    seq = event.get("seq")
    if not isinstance(seq, int) or isinstance(seq, bool):
        return False
    predecessor = next(
        (
            candidate
            for candidate in events
            if isinstance(candidate, dict) and candidate.get("seq") == seq - 1
        ),
        None,
    )
    return (
        event.get("type") == TYPE_ASSET_OPERATION_COMMITTED
        and isinstance(predecessor, dict)
        and predecessor.get("type") == TYPE_CHAIN_DISPATCH_REORGED
        and event.get("request_id") is not None
        and event.get("request_id") == predecessor.get("request_id")
    )


def _order_reorg_committed_details(events: list) -> None:
    """把重组补偿提交事件（紧邻 chain_dispatch_reorged 的同 request_id
    asset_operation_committed）的 details 就地重排为 R 键序。

    仅当 details 键集恰为 R 六键时重排；畸形现场留给语义对账 fail-closed。
    其余提交事件的 details 维持原序（普通提交维持 sort_keys 序）。"""
    for index, event in enumerate(events):
        if not _reorg_compensation_commit(events, index):
            continue
        details = event.get("details")
        if isinstance(details, dict) and set(details) == set(
            _ASSET_OPERATION_R_KEY_ORDER
        ):
            event["details"] = {
                key: details[key] for key in _ASSET_OPERATION_R_KEY_ORDER
            }


def _canonical_event(
    event: object, preserve_details_order: bool = False
) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。

    preserve_details_order 为真时，details 即使不在 _DETAILS_KEY_ORDER
    （重组补偿提交事件 asset_operation_committed）也按已归一的 R 键序原样
    保序，不随 sort_keys 重排。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if key == "details" and isinstance(value, dict) and (
            event.get("type") in _DETAILS_KEY_ORDER
            or preserve_details_order
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            # 重组补偿提交事件的 details 按 README 的 R 序落盘（不随
            # sort_keys 被重排为 state 先于 delta 的规范序）。
            _order_reorg_committed_details(value)
            canonical[key] = [
                _canonical_event(
                    event,
                    preserve_details_order=_reorg_compensation_commit(
                        value, index
                    ),
                )
                for index, event in enumerate(value)
            ]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        # 既定事件类型的 details 在内存视图中归一为 README 既定键序，
        # 使查询/重建/重写（落盘与灾备）都按该顺序保序。
        #
        # 但归一化会就地重排键序，必须**先**对落盘原序严格的类型核对其
        # 落盘 details 键序：错序即外部篡改/不可对账（RecoveryError），
        # 绝不先归一再校验而把错序静默抹平。审计 JSON 本身解析失败已在
        # WalletStore._read_json 处抛 CorruptDataError。
        for event in events:
            if event.get("type") in _STRICT_OUTER_ORDER_TYPES and list(
                event
            ) != list(_OUTER_KEY_ORDER):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose outer fields are out "
                    "of the canonical order"
                )
            if (
                event.get("type") in _STRICT_DETAILS_ORDER_TYPES
                and not _stored_details_has_canonical_order(event)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose details are out of "
                    "the canonical order"
                )
        # 重组补偿三事件批的收尾提交事件（seq-1 为同 request_id 的
        # chain_dispatch_reorged）的 asset_operation_committed.details 必须
        # 按 README 的 R 序落盘；错序即在归一化之前 fail-closed，绝不先
        # 归一而抹平重排。按 seq 邻接判定（物理顺序允许被外部重排）。
        by_seq = {event["seq"]: event for event in events}
        for event in events:
            if event.get("type") != TYPE_ASSET_OPERATION_COMMITTED:
                continue
            predecessor = by_seq.get(event["seq"] - 1)
            if not (
                isinstance(predecessor, dict)
                and predecessor.get("type") == TYPE_CHAIN_DISPATCH_REORGED
                and predecessor.get("request_id") is not None
                and predecessor.get("request_id") == event.get("request_id")
            ):
                continue
            details = event.get("details")
            if (
                not isinstance(details, dict)
                or list(details) != list(_ASSET_OPERATION_R_KEY_ORDER)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has an "
                    "asset_operation_committed event for a reorg "
                    "compensation whose details are out of the R order"
                )
        for event in events:
            _order_event_details(event)
        # 重组补偿提交事件的 details 在内存视图中同样归一为 R 序（落盘与
        # 恢复一致）；普通提交事件维持既有 sort_keys 序不变。
        _order_reorg_committed_details(events)
        # 防篡改摘要链：按读取归一化后的事件（七字段含 details，键升序
        # 紧凑 JSON）重算链头，与顶层 chain 对象对账。旧记录可能缺链
        # （只读路径容忍，由追加/备份持锁补算，不改写事件正文）；链一旦
        # 存在，任何元数据形状或摘要矛盾都 fail-closed（RecoveryError），
        # 绝不覆盖现场。
        try:
            count, head = compute_chain_head(events)
        except (TypeError, KeyError, ValueError) as exc:
            raise RecoveryError(
                f"audit log {path!r} has an event that cannot be hashed "
                f"into the chain: {exc}"
            ) from exc
        if "chain" in data:
            _validate_stored_chain(path, data.get("chain"), count, head)
        return data

    def check_log(self, wallet_id: str) -> None:
        """只读严格校验审计文件；损坏抛 CorruptDataError/OSError。
        文件不存在（尚无事件）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_strict(wallet_id)

    def integrity(self, wallet_id: str) -> tuple[int, str]:
        """校验并返回该钱包审计摘要链的 ``(count, head)``。

        无审计文件视为空链：count=0、head 为 64 个零字符。文件存在但缺

def _validate_operation_id(operation_id: object) -> None:
    if not isinstance(operation_id, str) or not ROTATION_ID_RE.match(
        operation_id
    ):
        raise ServiceError(
            400, "operation_id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_asset_id(asset_id: object) -> None:
    if not isinstance(asset_id, str) or not ROTATION_ID_RE.match(
        asset_id
    ):
        raise ServiceError(
            400, "asset_id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_delta(delta: object) -> None:
    # bool 是 int 的子类，必须先排除；0 不是合法的资产变动
    if not isinstance(delta, int) or isinstance(delta, bool) or delta == 0:
        raise ServiceError(400, "delta must be a non-zero integer")

@staticmethod
def _validate_cancel_id(cancel_id: object) -> None:
    if not isinstance(cancel_id, str) or not ROTATION_ID_RE.match(
        cancel_id
    ):
        raise ServiceError(
            400, "cancel_id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_approval_request_id_ref(approval_request_id: object) -> None:
    if not isinstance(
        approval_request_id, str
    ) or not ROTATION_ID_RE.match(approval_request_id):
        raise ServiceError(
            400,
            "approval_request_id must match [A-Za-z0-9_-]{1,128}",
        )

@staticmethod
def _cancel_approval_message(
    operation_id: str, cancel_id: str
) -> str:
    """撤销审批单 message 必须逐字一致的紧凑 JSON（无空格、键序固定
    为 operation_id,cancel_id）。"""
    return json.dumps(
        {
            "operation_id": operation_id,
            "cancel_id": cancel_id,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )

def create_asset_operation(
    self,
    wallet_id: str,
    operation_id: object,
    asset_id: object,
    delta: object,
) -> tuple[int, dict]:
    """创建一条资产操作（pending）。返回 (HTTP 状态码, 响应体 R)。

    首次创建 201；同 operation_id 同参数幂等重放 200（返回当前记录，
    不重复记事件、不再按当前策略校验）；同 operation_id 异参数 409。
    创建本身不记审计事件。

    钱包配置了冷热钱包交易策略时，**仅首次创建**按创建时刻的策略
    检查：asset_id 必须在 allowed_assets 白名单内且
    ``abs(delta) <= max_delta``，否则 409 且账本/version/状态/审计/
    幂等结果均不变（检查发生在任何写入之前）。策略后续更新不影响
    已存在的 pending 操作；未配置策略时行为完全不变。

    恢复检查、钱包存在性、参数校验、幂等查重与策略读取全部在锁内：
    绝不基于锁外快照决定 404/400/409、重放或白名单结果。
    """
    record: dict | None = None
    try:
        with self._wallet_lock(wallet_id):
            # 快照前先自愈他进程崩溃遗留的提交意图，balance/version 才准确
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性先于 id/delta 校验
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            self._validate_operation_id(operation_id)
            self._validate_asset_id(asset_id)
            self._validate_delta(delta)
            existing = self._store.get_asset_operation(
                wallet_id, operation_id
            )
            if existing is not None:
                # 重放：原样返回磁盘中的当前记录，不按更新后的策略重新
                # 校验、不改状态、不记事件（幂等结果不变）
                if (
                    existing.get("asset_id") != asset_id
                    or existing.get("delta") != delta
                ):
                    raise ServiceError(
                        409,
                        f"asset operation {operation_id!r} already exists "
                        "with different parameters",
                    )
                return 200, existing
            # 首次创建：按锁提交时刻的交易策略检查白名单与单笔上限
            policy = self._store.get_transaction_policy(wallet_id)
            if policy is not None:
                if asset_id not in policy["allowed_assets"]:
                    raise ServiceError(
                        409,
                        f"asset {asset_id!r} is not allowed by the "
                        "transaction policy",
                    )
                if abs(delta) > policy["max_delta"]:
                    raise ServiceError(
                        409,
                        f"abs(delta)={abs(delta)} exceeds transaction "
                        f"policy max_delta={policy['max_delta']}",
                    )
            # R 的 balance/version 快照资产在创建时刻的账本状态
            asset = self._store.get_asset(wallet_id, asset_id)
            record = {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "state": "pending",
                "delta": delta,
                "balance": asset["balance"] if asset is not None else 0,
                "version": asset["version"] if asset is not None else 0,
            }
            # 锁内已确认不存在；存储层仍原子查重兜底
            self._store.create_asset_operation(
                wallet_id, operation_id, record
            )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, record

# ---- 资产提交的崩溃恢复 ----------------------------------------------

def _recover_wallet_asset_commits(self, wallet_id: str) -> None:
    """恢复某钱包全部未完成的资产提交事务（调用方须持有钱包事务锁）。

    以 asset_operation_committed 事件是否已持久化作为唯一提交判据：
    - 事件在：提交已生效，按事件 details（即 committed 视图 R）把账本
      前滚补齐为一致的 committed 结果，再删意图（幂等，余额/版本按 R
      绝对值校正，不重复应用 delta）；
    - 事件不在：提交未生效，按意图记录的提交前快照把操作恢复为
      pending、资产恢复提交前 balance/version（提交前不存在则删除
      资产条目），再删意图。事件从未分配 seq，故无 seq 缺口。
    恢复本身不记任何审计事件。任一条意图无法对账到一致状态都抛
    RecoveryError，由调用方阻止就绪/返回 503，绝不静默跳过。
    """
    for operation_id, intent in self._store.list_asset_intents(wallet_id):
        # 撤销意图与提交意图共用 asset-intents 目录（同操作在锁内
        # 互斥，崩溃至多残留其一）：按 kind 分派，未知 kind 是无法
        # 识别的事务现场，fail-closed 绝不按任一已知事务猜测对账。
        if isinstance(intent, dict) and intent.get("kind") == "cancel":
            self._resolve_asset_cancel_intent(
                wallet_id, operation_id, intent
            )
            continue
        if isinstance(intent, dict) and "kind" in intent:
            raise RecoveryError(
                f"wallet {wallet_id!r} asset operation {operation_id!r} "
                "intent has an unknown kind and cannot be reconciled"
            )
        self._resolve_asset_commit_intent(wallet_id, operation_id, intent)

def _reconcile_asset_committed_events(self, wallet_id: str) -> None:
    """账本 committed 操作与 asset_operation_committed 事件双向对账
    （调用方须持钱包事务锁；意图残留须已先恢复清零）。

    唯一提交点是审计事件：

    - 每条 committed 操作必须恰有一条同 request_id 的事件，
      ``details`` 与账本中的 committed 视图 R 逐字段一致；
    - 每条 committed 事件必须对应一条账本 committed 操作
      （有事件无操作＝事件被半应用或历史被删，fail-closed）；
    - pending 操作不得有 committed 事件；
    - 同一 operation_id 出现多条 committed 事件＝重复提交点，
      fail-closed。

    审计日志损坏（CorruptDataError）同样向上抛出，由调用方 fail-closed。
    """
    ledger = self._store.check_asset_ledger_semantics(wallet_id)
    committed_ops: dict[str, dict] = {
        op_id: record
        for op_id, record in ledger["operations"].items()
        if record["state"] == "committed"
    }
    pending_ops = {
        op_id
        for op_id, record in ledger["operations"].items()
        if record["state"] == "pending"
    }

    无审计文件视为空链：count=0、head 为 64 个零字符。文件存在但缺
    chain 元数据（尚未迁移的旧记录）与链元数据/事件摘要矛盾一样属于
    不可对账现场，抛 RecoveryError（调用方转 503，保留现场不覆盖）；
    JSON 损坏抛 CorruptDataError、I/O 失败抛 OSError。"""
    data = self._read_strict(wallet_id)
    if data is None:
        return 0, GENESIS_HEAD
    if "chain" not in data:
        raise RecoveryError(
            f"audit log for wallet {wallet_id!r} is missing its chain "
            "metadata"
        )
    chain = data["chain"]
    return chain["count"], chain["head"]

def backfill_chain(self, wallet_id: str) -> None:
    """为缺链的旧记录补算并持久化 chain 元数据（迁移点）。

    仅在 chain 缺失时按事件顺序一次性重算写入，绝不改写事件正文；
    chain 已存在（严格加载已验通）时为无操作；chain 存在但不匹配时
    抛 RecoveryError 且绝不覆盖现场。调用方须持该钱包事务锁。"""
    path = self._path(wallet_id)
    with self._lock:
        data = self._read_strict(wallet_id)
        if data is None or "chain" in data:
            return
        count, head = compute_chain_head(data["events"])
        data["chain"] = {
            "algorithm": CHAIN_ALGORITHM,
            "head": head,
            "count": count,
        }
        _atomic_write_log(path, data)

def list_audit_wallet_ids(self) -> list[str]:
    """返回存在审计文件的全部 wallet_id（启动恢复扫描用）。"""
    try:
        names = os.listdir(self._audit_dir)
    except FileNotFoundError:
        return []
    return sorted(
        name[: -len(".json")]
        for name in names
        if name.endswith(".json")
        and _safe_id_match(name[: -len(".json")])
    )

def _read(self, wallet_id: str) -> Optional[dict]:
    return self._read_strict(wallet_id)

def append_event(self, wallet_id: str, event: dict) -> dict:
    """原子追加一条事件，分配下一个 seq 并持久化，返回含 seq/at 的记录。

    seq 从 1 起；同一 wallet 的写入在此串行化。调用方负责在更大的
    每钱包事务锁内把状态变更与本调用绑定（失败时回滚状态）。

    既有日志损坏 / seq 矛盾时抛 CorruptDataError，绝不把历史清空后
    继续写（那会用一条新事件覆盖全部审计历史）。
    """
    return self.append_events(wallet_id, [event])[0]

def append_events(self, wallet_id: str, events: list[dict]) -> list[dict]:
    """原子追加一批事件：一次落盘分配连续 seq（n、n+1、…），返回含
    seq/at 的记录列表。

    整批要么全部持久化、要么全部不持久化（同目录临时文件 +
    os.replace 原子替换）：多条事件构成同一提交点（如达门槛
    chain_report 与紧邻的 asset_operation_committed）时使用，崩溃
    窗口内绝不出现只落前半截的日志，也不留 seq 缺口。

    语义与单条追加相同：严格加载既有日志（损坏 / seq 矛盾抛
    CorruptDataError，绝不清空历史后续写），seq 从 1 起连续分配；
    调用方负责在每钱包事务锁内把状态变更与本调用绑定。
    """
    if not events:
        raise ValueError("events must be a non-empty list")
    path = self._path(wallet_id)
    with self._lock:
        data = self._read_strict(wallet_id)
        if data is None:
            data = {"wallet_id": wallet_id, "next_seq": 1, "events": []}
        existing = data["events"]
        # 严格加载已保证 1..N 连续：下一个 seq 直接取 N+1，
        # 与 next_seq（兼容缺字段的旧文件）一致。
        next_seq = len(existing) + 1
        stamped_events = []
        for event in events:
            stamped = dict(event)
            stamped["seq"] = next_seq
            # 既定事件类型的 details 落盘前归一为 README 既定键序
            _order_event_details(stamped)
            existing.append(stamped)
            stamped_events.append(stamped)
            next_seq += 1
        data["next_seq"] = next_seq
        # 防篡改摘要链：旧记录缺链时连同既有事件一起按顺序补算
        # （不改动任何事件正文）；链已存在时严格加载已验通既有段，
        # 此处对追加后的完整事件序列重算，与新事件一次原子落盘。
        count, head = compute_chain_head(existing)
        data["chain"] = {
            "algorithm": CHAIN_ALGORITHM,
            "head": head,
            "count": count,
        }
        _atomic_write_log(path, data)
        return stamped_events

def find_event_by_request(
    self,
    wallet_id: str,
    event_type: str,
    request_id: str,
) -> Optional[dict]:
    """按 (类型, request_id) 查找一条已持久化事件，不存在返回 None。

    启动恢复据此判定崩溃前的资产提交事务是否已把事件落盘：事件在
    则补齐账本，事件不在则回滚为 pending。纯只读，不分配 seq。
    """
    data = self._read(wallet_id)
    if not data:
        return None
    for event in data.get("events", []):
        if (
            isinstance(event, dict)
            and event.get("type") == event_type
            and event.get("request_id") == request_id
        ):
            return dict(event)
    return None

def find_session_event(
    self, wallet_id: str, request_id: str, action: str
) -> Optional[dict]:
    """按 (request_id, details.action) 查找一条 session_event。

    签名会话崩溃恢复据此判定创建/签名是否已提交：事件在则状态不可
    撤回（前滚），事件不在则回滚。纯只读，不分配 seq。
    """
    for event in self.session_events(wallet_id).get(request_id, []):
        details = event.get("details")
        if isinstance(details, dict) and details.get("action") == action:
            return dict(event)
    return None

def session_events(self, wallet_id: str) -> dict[str, list[dict]]:
    """返回该钱包全部 session_event，按 request_id（会话 id）分组。

    签名会话崩溃恢复一次性读取审计文件，据此判定每个会话哪些动作
    （created/share_received/expired/signed）已经提交。纯只读。"""
    data = self._read(wallet_id)
    result: dict[str, list[dict]] = {}
    if not data:
        return result
    for event in data.get("events", []):
        if not isinstance(event, dict):
            continue
        if event.get("type") != TYPE_SESSION_EVENT:
            continue
        request_id = event.get("request_id")
        if isinstance(request_id, str):
            result.setdefault(request_id, []).append(dict(event))
    return result

def _events_grouped_by_request(
    self, wallet_id: str, event_type: str
) -> dict[str, list[dict]]:
    """返回该钱包指定类型的全部事件，按 request_id 分组，组内按 seq
    升序。纯只读，不分配 seq。"""
    data = self._read(wallet_id)
    result: dict[str, list[dict]] = {}
    if not data:
        return result
    for event in data.get("events", []):
        if not isinstance(event, dict):
            continue
        if event.get("type") != event_type:
            continue
        request_id = event.get("request_id")
        if isinstance(request_id, str):
            result.setdefault(request_id, []).append(dict(event))
    for events in result.values():
        events.sort(key=lambda e: e.get("seq", 0))
    return result

def session_participant_replaced_events(
    self, wallet_id: str
) -> dict[str, list[dict]]:
    """返回该钱包全部 session_participant_replaced 事件，按 request_id
    （会话 id）分组，组内按 seq 升序。

